// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));

        vm.assume(caller != address(0));

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        address currentOwner = c.owner();

        if (currentOwner != caller) {
            assertTrue(!ok);
        } else {
            assertTrue(true);
        }
    }
}
